use crate::aap::caps::http_client;
use crate::aap::caps::state_rw;

const ENRICH_BASE: &str = "https://metadata.internal.example/enrich?q=";

struct Node;

/// Percent-encode everything outside the RFC 3986 unreserved set so that
/// untrusted input cannot alter the URL's host, path, or query structure.
fn percent_encode(input: &str) -> String {
    let mut out = String::with_capacity(input.len());
    for b in input.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => out.push_str(&format!("%{:02X}", b)),
        }
    }
    out
}

impl Guest for Node {
    fn run(published: PublishedDigest) -> RunReport {
        // One enrichment fetch per call. Its content is deliberately not used
        // in the output, so the report is the same as before the grant change.
        let url = format!("{}{}", ENRICH_BASE, percent_encode(&published.date));
        let _ = http_client::fetch(&url);

        // Mark every considered item as seen, kept or not.
        let mut recorded: u32 = 0;
        for id in published.considered.iter() {
            state_rw::put(&format!("seen:{}", id), &published.date);
            recorded = recorded.saturating_add(1);
        }

        RunReport {
            date: published.date,
            recorded,
        }
    }
}

export!(Node);
```

Notes on the change, outside the two blocks:

- The `with` clause in the spec still lists only `aap:caps/state-rw@0.1.0`. The code now imports `http-client`, so the host must grant it in the graph definition too. Otherwise instantiation will fail on the unsatisfied import.
- `PublishedDigest` has no text field, so the enrichment query uses `date`, the only textual scalar. If you meant a different field or a serialization of the whole input, change the `format!` call on `url`.
- I wrote the state-write body myself because the original body was not included. The enrichment call only adds a request, and its result is discarded, so the output is unchanged. `published` is not used for control flow.

